// @generated by:gauntlet run:g-o-d-s-e-y-e-cfe8
import { randomUUID } from "node:crypto";
import { ControlPlane } from "@godseye/core";
import { openStore, type Store } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  githubPush,
  owner,
  projectInput,
  repository,
  signedDelivery,
  webhookKey,
} from "./helpers.js";

// T-AC-04: verify bytes, binding and delivery identity; acceptance is pending verification.
describe("signed GitHub intake", () => {
  let store: Store;
  let core: ControlPlane;

  beforeEach(async () => {
    store = await openStore();
    core = new ControlPlane(store);
    const project = await core.createProject(owner, projectInput, randomUUID());
    await core.configureRepository(owner, project.id, repository, project.revision, randomUUID());
  });

  afterEach(async () => {
    await store.close();
  });

  it("T41 queues a matching push for verification without claiming a successful build", async () => {
    const result = await core.receiveGithubDelivery(signedDelivery(), webhookKey);

    expect(result.outcome).toBe("queued");
    const runs = await core.listCiRuns(owner);
    expect(runs).toHaveLength(1);
    expect(runs[0]).toMatchObject({
      id: result.runId,
      branch: "main",
      commitSha: "a".repeat(40),
      status: "pending_verification",
      trigger: "push",
    });
  });

  it("T41 authenticates exact bytes and rejects a reserialized payload using the old signature", async () => {
    const valid = signedDelivery(JSON.stringify(githubPush(), null, 2));
    const changedBytes = { ...valid, rawBody: Buffer.from(JSON.stringify(githubPush())) };

    await expect(core.receiveGithubDelivery(changedBytes, webhookKey)).rejects.toMatchObject({
      status: 401,
    });
    expect(await core.listCiRuns(owner)).toHaveLength(0);
    expect((await core.receiveGithubDelivery(valid, webhookKey)).outcome).toBe("queued");
  });

  it.each([undefined, "", "sha1=123", "sha256=00", `sha256=${"z".repeat(64)}`])(
    "T41 rejects absent or malformed signature %s without creating a run",
    async (signature) => {
      const delivery = { ...signedDelivery(), signature };

      await expect(core.receiveGithubDelivery(delivery, webhookKey)).rejects.toMatchObject({
        status: 401,
      });
      expect(await core.listCiRuns(owner)).toHaveLength(0);
    },
  );

  it("T41 rejects a correct-shaped signature made with another key", async () => {
    const delivery = signedDelivery(githubPush(), { key: "untrusted-fixture-key" });

    await expect(core.receiveGithubDelivery(delivery, webhookKey)).rejects.toMatchObject({
      status: 401,
    });
    expect(await core.listCiRuns(owner)).toHaveLength(0);
  });

  it("T41 accepts a delivery only once when GitHub retries it concurrently", async () => {
    const delivery = signedDelivery();

    const results = await Promise.all(
      Array.from({ length: 5 }, () => core.receiveGithubDelivery(delivery, webhookKey)),
    );

    expect(results.filter((result) => result.outcome === "queued")).toHaveLength(1);
    expect(results.filter((result) => result.outcome === "duplicate")).toHaveLength(4);
    expect(await core.listCiRuns(owner)).toHaveLength(1);
  });

  it("T41 rejects a delivery identifier reused for different authenticated bytes", async () => {
    const deliveryId = randomUUID();
    await core.receiveGithubDelivery(signedDelivery(githubPush(), { deliveryId }), webhookKey);

    await expect(
      core.receiveGithubDelivery(
        signedDelivery(githubPush({ after: "b".repeat(40) }), { deliveryId }),
        webhookKey,
      ),
    ).rejects.toMatchObject({ code: "DELIVERY_CONFLICT", status: 409 });
    expect(await core.listCiRuns(owner)).toHaveLength(1);
  });

  it.each([
    {
      name: "another repository id",
      overrides: { repository: { id: 999, full_name: repository.fullName } },
    },
    {
      name: "another repository name",
      overrides: { repository: { id: repository.repositoryId, full_name: "other/repository" } },
    },
    { name: "another installation", overrides: { installation: { id: 999 } } },
    { name: "an unbound branch", overrides: { ref: "refs/heads/develop" } },
    { name: "a tag", overrides: { ref: "refs/tags/main" } },
    { name: "a deleted branch", overrides: { deleted: true } },
  ])("T41 ignores $name even when its payload is correctly signed", async ({ overrides }) => {
    const result = await core.receiveGithubDelivery(
      signedDelivery(githubPush(overrides)),
      webhookKey,
    );

    expect(result.outcome).toBe("ignored");
    expect(await core.listCiRuns(owner)).toHaveLength(0);
  });

  it("T41 ignores signed events outside the subscribed push workflow", async () => {
    const result = await core.receiveGithubDelivery(
      signedDelivery({}, { event: "ping" }),
      webhookKey,
    );

    expect(result.outcome).toBe("ignored");
    expect(await core.listCiRuns(owner)).toHaveLength(0);
  });

  it.each([
    { name: "invalid JSON", payload: "{broken" },
    { name: "missing repository", payload: githubPush({ repository: undefined }) },
    { name: "missing installation", payload: githubPush({ installation: undefined }) },
    { name: "invalid commit", payload: githubPush({ after: "not-a-sha" }) },
    { name: "zero commit", payload: githubPush({ after: "0".repeat(40) }) },
  ])("T41 rejects $name without creating a run", async ({ payload }) => {
    await expect(
      core.receiveGithubDelivery(signedDelivery(payload), webhookKey),
    ).rejects.toMatchObject({ status: 400 });
    expect(await core.listCiRuns(owner)).toHaveLength(0);
  });
});
